css:
/* =========================================================
   Connect Diagnostics — Shared A4 Print Base
   Suggested app path:
   connect_diagnostics_core/public/css/cd_print_base.css

   Documents using this base should put BOTH classes on the article:
   class="cd-print cd-so"
   class="cd-print cd-gr"
   class="cd-print cd-pr"
   etc.
   ========================================================= */

@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: 210mm 297mm;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  width: 210mm !important;
  min-width: 210mm !important;
  max-width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
  background: #fff !important;
  overflow: visible !important;
}

.cd-print,
.cd-print * {
  box-sizing: border-box;
}

.cd-print {
  --cd-document-ink: #202020;
  --cd-document-muted: #5f6368;
  --cd-document-border: #202020;
  --cd-document-surface: #f1f1f1;
  --cd-document-accent: #e2a2f5;

  position: relative;
  width: 210mm;
  height: 297mm;
  margin: 0;
  padding: 0;
  overflow: hidden;

  color: var(--cd-document-ink);
  background: #fff;

  font-family:
    "TH Sarabun Document",
    "Noto Sans Thai",
    "TH Sarabun New",
    "TH SarabunPSK",
    sans-serif;

  font-size: 4.60mm;
  font-weight: 400;
  line-height: 1;

  page-break-after: always;

  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.cd-print.last-page {
  page-break-after: auto;
}

.cd-print p,
.cd-print table,
.cd-print dl,
.cd-print dt,
.cd-print dd {
  margin: 0;
  padding: 0;
}

.cd-print .label-th,
.cd-print .label-en {
  display: block;
  white-space: nowrap;
}

.cd-print .label-th {
  font-size: 4.46mm;
  line-height: 3.82mm;
}

.cd-print .label-en {
  font-size: 3.34mm;
  line-height: 2.82mm;
}

/* =========================================================
   SHARED HEADER
   ========================================================= */

.cd-print .document-header {
  position: absolute;
  left: 0;
  top: 0;
  width: 210mm;
  height: 52.30mm;
}

.cd-print .company-logo {
  position: absolute;
  left: 12.70mm;
  top: 18.56mm;
  width: 18.99mm;
  height: 7.25mm;
  object-fit: contain;
}

.cd-print .company-name {
  position: absolute;
  left: 34.28mm;
  top: 13.62mm;
  width: 95mm;
  overflow: hidden;
  font-size: 6.90mm;
  font-weight: 700;
  line-height: 7.60mm;
  white-space: nowrap;
}

.cd-print .company-address {
  position: absolute;
  left: 34.28mm;
  top: 22.82mm;
  width: 156mm;
  overflow: hidden;
  font-size: 4.60mm;
  line-height: 5.25mm;
  white-space: nowrap;
}

.cd-print .company-contact {
  position: absolute;
  left: 34.28mm;
  top: 29.02mm;
  font-size: 4.60mm;
  line-height: 5.25mm;
  white-space: nowrap;
}

.cd-print .company-tax-label,
.cd-print .company-tax-value,
.cd-print .company-branch {
  position: absolute;
  top: 35.63mm;
  font-size: 4.46mm;
  line-height: 5.50mm;
  white-space: nowrap;
}

.cd-print .company-tax-label {
  left: 34.28mm;
  width: 39.0mm;
  overflow: hidden;
}

.cd-print .company-tax-value {
  left: 74mm;
  width: 24mm;
  overflow: hidden;
}

.cd-print .company-branch {
  left: 99mm;
  width: 32mm;
  overflow: visible;
  padding: 0;
}

.cd-print .document-title,
.cd-print .copy-title {
  position: absolute;
  left: 131.48mm;
  width: 59mm;

  display: flex;
  align-items: center;
  justify-content: center;

  text-align: center;
  white-space: nowrap;
}

.cd-print .document-title {
  top: 40.75mm;
  height: 6.80mm;
  padding: 0 2mm;
  border-radius: 6mm;
  background: var(--cd-document-accent);
  font-size: 5.25mm;
  font-weight: 700;
  line-height: 1;
}

.cd-print .copy-title {
  top: 48.20mm;
  height: 5.00mm;
  font-size: 4.10mm;
  font-weight: 700;
  line-height: 1;
}

/* =========================================================
   SHARED BOX / SIGNATURE PRIMITIVES
   ========================================================= */

.cd-print .info-box {
  position: relative;
  overflow: hidden;
  border: 0.28mm solid var(--cd-document-border);
  border-radius: 3.0mm;
  background: #fff;
}

.cd-print .signature-section {
  position: relative;
  height: 32.80mm;

  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: center;

  border-top: 0.28mm solid var(--cd-document-border);
}

.cd-print .signature-block {
  height: 100%;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  padding-top: 2.4mm;
  text-align: center;
}

.cd-print .signature-block + .signature-block {
  border-left: 0.28mm solid var(--cd-document-border);
}

.cd-print .signature-line {
  width: 39mm;
  height: 0;
  margin-bottom: 1.65mm;
  border-top: 0.24mm solid var(--cd-document-border);
}

.cd-print .signature-title {
  font-size: 4.05mm;
  line-height: 4.55mm;
  white-space: nowrap;
}

.cd-print .signature-date {
  margin-top: 1.65mm;
  font-size: 3.58mm;
  line-height: 4.00mm;
  letter-spacing: 0.12mm;
}

.cd-print .page-number {
  position: absolute;
  right: 2.8mm;
  bottom: 1.8mm;
  z-index: 3;

  padding-left: 1.2mm;
  background: #fff;

  color: var(--cd-document-muted);
  font-size: 3.10mm;
  line-height: 3.60mm;
  white-space: nowrap;
}

@media print {
  .cd-print {
    margin: 0 !important;
    box-shadow: none !important;
  }
}


/* =========================================================
   Connect Diagnostics — Sales Order
   Requires cd_print_base.css when used in shared mode.
   ========================================================= */

/* =========================================================
   DOCUMENT INFO
   ========================================================= */

.cd-so .document-info {
  position: absolute;
  left: 12.70mm;
  top: 55.40mm;
  width: 184.60mm;
  height: 49.80mm;

  display: grid;
  grid-template-columns: 1.28fr 1fr;
  column-gap: 1.55mm;
}

.cd-so .info-box {
  height: 49.80mm;
}

/* -------------------------
   Customer box
   ------------------------- */

.cd-so .customer-box {
  padding: 3.0mm 3.9mm 2.7mm;
}

.cd-so .customer-heading {
  display: flex;
  align-items: flex-start;
  min-height: 6.25mm;
}

.cd-so .customer-heading .compact-label {
  flex: 0 0 23mm;
  width: 23mm;
}

.cd-so .customer-code {
  min-width: 0;
  padding-top: 0.15mm;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 4.58mm;
  line-height: 5.05mm;
}

.cd-so .customer-name {
  margin-top: 0.55mm;
  max-width: 95mm;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 4.52mm;
  line-height: 5.00mm;
}


.cd-so .ship-to-value p {
  display: inline;
}

.cd-so .ship-to-row {
  position: absolute;
  left: 3.9mm;
  right: 3.9mm;
  top: 14.40mm;
  height: 20.00mm;

  display: grid;
  grid-template-columns: 22mm minmax(0, 1fr);
  align-items: start;
}

.cd-so .customer-contact-row {
  position: absolute;
  left: 3.9mm;
  right: 3.9mm;
  bottom: 2.55mm;
  min-height: 6.30mm;

  display: grid;
  grid-template-columns: 22mm minmax(0, 1fr);
  align-items: center;
}

.cd-so .mini-label .label-th,
.cd-so .mini-label .label-en {
  line-height: 2.90mm;
}

.cd-so .mini-label .label-th {
  font-size: 4.02mm;
}

.cd-so .mini-label .label-en {
  font-size: 3.05mm;
}

.cd-so .mini-value {
  padding-top: 0.45mm;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 4.10mm;
  line-height: 4.60mm;
}

.cd-so .ship-to-value {
  max-height: 18.00mm;
  padding-top: 0.35mm;
  overflow: hidden;
  font-size: 3.72mm;
  line-height: 4.05mm;
}


/* -------------------------
   Order metadata
   ------------------------- */

.cd-so .order-box {
  padding: 2.75mm 3.35mm 2.40mm;
}

.cd-so .order-fields {
  width: 100%;
  height: 100%;

  display: grid;
  grid-template-columns: 26.0mm 21.0mm 9.5mm minmax(0, 1fr);
  grid-template-rows:
    5.40mm
    5.40mm
    5.40mm
    5.40mm
    5.40mm
    5.40mm
    5.40mm
    5.40mm;

  align-items: start;
}

.cd-so .order-fields > .field-label {
  padding-top: 0.10mm;
}

.cd-so .order-fields > .field-label .label-th,
.cd-so .order-fields > .field-label .label-en {
  line-height: 2.60mm;
}

.cd-so .order-fields > .field-label .label-th {
  font-size: 3.82mm;
}

.cd-so .order-fields > .field-label .label-en {
  font-size: 2.82mm;
}

.cd-so .field-value {
  min-width: 0;
  padding-top: 0.35mm;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 4.02mm;
  line-height: 4.50mm;
}

.cd-so .document-no {
  font-weight: 700;
}

.cd-so .document-no-label       { grid-column: 1;     grid-row: 1; }
.cd-so .document-no             { grid-column: 2 / 5; grid-row: 1; }

.cd-so .document-date-label     { grid-column: 1;     grid-row: 2; }
.cd-so .document-date-value     { grid-column: 2 / 5; grid-row: 2; }

.cd-so .delivery-date-label     { grid-column: 1;     grid-row: 3; }
.cd-so .delivery-date-value     { grid-column: 2 / 5; grid-row: 3; }

.cd-so .po-label                { grid-column: 1;     grid-row: 4; }
.cd-so .po-value                { grid-column: 2;     grid-row: 4; }
.cd-so .po-date-label           { grid-column: 3;     grid-row: 4; }
.cd-so .po-date-value           { grid-column: 4;     grid-row: 4; }

.cd-so .sales-label             { grid-column: 1;     grid-row: 5; }
.cd-so .sales-value             { grid-column: 2 / 5; grid-row: 5; }

.cd-so .territory-label         { grid-column: 1;     grid-row: 6; }
.cd-so .territory-value         { grid-column: 2 / 5; grid-row: 6; }

.cd-so .payment-label           { grid-column: 1;     grid-row: 7; }
.cd-so .payment-value           { grid-column: 2 / 5; grid-row: 7; }

.cd-so .delivery-by-label       { grid-column: 1;     grid-row: 8; }
.cd-so .delivery-by-value       { grid-column: 2;     grid-row: 8; }

.cd-so .currency-label          { grid-column: 3;     grid-row: 8; }
.cd-so .currency-value          { grid-column: 4;     grid-row: 8; }

.cd-so .po-value,
.cd-so .po-date-value,
.cd-so .currency-value {
  font-size: 3.78mm;
}

/* =========================================================
   MAIN ORDER BODY — SHARED OUTER BORDER
   ========================================================= */

.cd-so .order-main {
  position: absolute;
  left: 12.70mm;
  top: 107.00mm;
  width: 184.60mm;
  height: 179.20mm;

  overflow: hidden;
  border: 0.28mm solid var(--cd-document-border);
  border-radius: 3.0mm;
  background: #fff;
}

/* =========================================================
   ITEMS TABLE
   ========================================================= */

.cd-so .items-table {
  width: 100%;
  height: 94.00mm;

  table-layout: fixed;
  border-collapse: collapse;
  border-spacing: 0;
}

.cd-so .items-table .col-no          { width: 5.8%; }
.cd-so .items-table .col-description { width: 45.2%; }
.cd-so .items-table .col-qty         { width: 14.0%; }
.cd-so .items-table .col-rate        { width: 13.0%; }
.cd-so .items-table .col-discount    { width: 10.0%; }
.cd-so .items-table .col-amount      { width: 12.0%; }

.cd-so .items-table th,
.cd-so .items-table td {
  border: 0;
  border-right: 0.28mm solid var(--cd-document-border);
}

.cd-so .items-table th:last-child,
.cd-so .items-table td:last-child {
  border-right: 0;
}

.cd-so .items-table thead tr {
  height: 10.80mm;
}

.cd-so .items-table thead th {
  padding: 1.15mm 0.70mm 0.75mm;
  border-bottom: 0.28mm solid var(--cd-document-border);
  text-align: center;
  vertical-align: middle;
  font-weight: 400;
}

.cd-so .table-head-th,
.cd-so .table-head-en {
  display: block;
  white-space: nowrap;
}

.cd-so .table-head-th {
  font-size: 4.34mm;
  line-height: 3.68mm;
}

.cd-so .table-head-en {
  font-size: 3.18mm;
  line-height: 2.62mm;
}

.cd-so .items-table tbody td {
  padding: 1.65mm 1.30mm 0.45mm;
  vertical-align: top;
  font-size: 4.02mm;
  line-height: 4.35mm;
}

.cd-so .items-table .item-row {
  height: 8.15mm;
}

.cd-so .items-table .cell-no {
  padding-right: 1.65mm;
  text-align: right;
}

.cd-so .items-table .cell-qty,
.cd-so .items-table .cell-discount {
  text-align: center;
  white-space: nowrap;
}

.cd-so .items-table .cell-money {
  padding-right: 1.30mm;
  text-align: right;
  white-space: nowrap;
}

.cd-so .item-main-line {
  min-width: 0;
  max-width: 100%;
  height: 4.35mm;

  display: flex;
  align-items: baseline;
  gap: 1.10mm;

  overflow: hidden;
  white-space: nowrap;
}

.cd-so .item-code {
  flex: 0 0 auto;
  font-weight: 700;
  white-space: nowrap;
}

.cd-so .item-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cd-so .item-inline-meta {
  flex: 0 0 auto;

  color: var(--cd-document-muted);

  font-size: 2.86mm;
  line-height: 3.15mm;
  white-space: nowrap;
}

.cd-so .qty-uom {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 0.95mm;
  white-space: nowrap;
}

.cd-so .qty-value,
.cd-so .uom-text {
  display: inline;
  margin: 0;
  font-size: inherit;
  line-height: inherit;
  white-space: nowrap;
}

.cd-so .filler-row td {
  padding: 0 !important;
}

/* =========================================================
   SUMMARY
   ========================================================= */

.cd-so .summary-section {
  display: grid;
  grid-template-columns: 60.5% 39.5%;
  height: 52.40mm;
  border-top: 0.28mm solid var(--cd-document-border);
}

.cd-so .remark-box {
  position: relative;
  padding: 2.75mm 3.00mm 2.50mm;
  overflow: hidden;
  border-right: 0.28mm solid var(--cd-document-border);
}

.cd-so .summary-label .label-th {
  font-size: 4.12mm;
  line-height: 3.52mm;
}

.cd-so .summary-label .label-en {
  font-size: 3.08mm;
  line-height: 2.60mm;
}

.cd-so .remark-text {
  margin-top: 1.35mm;
  max-height: 29.5mm;
  overflow: hidden;
  font-size: 3.75mm;
  line-height: 4.10mm;
}

.cd-so .remark-text p {
  margin: 0 0 0.55mm 0;
}

.cd-so .amount-in-words {
  position: absolute;
  left: 3.0mm;
  right: 3.0mm;
  bottom: 2.5mm;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 3.92mm;
  line-height: 4.40mm;
}

.cd-so .continued-message {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4.20mm;
}

.cd-so .totals-box {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.cd-so .total-row {
  flex: 1 1 0;
  min-height: 0;

  display: grid;
  grid-template-columns: minmax(0, 1fr) 29.5mm;
  align-items: center;
}

.cd-so .total-label {
  position: relative;
  padding: 0.35mm 2.0mm 0.20mm 2.8mm;
}

.cd-so .total-label .label-th {
  font-size: 3.92mm;
  line-height: 3.28mm;
}

.cd-so .total-label .label-en {
  font-size: 2.95mm;
  line-height: 2.45mm;
}

.cd-so .total-value {
  height: 100%;

  display: flex;
  align-items: center;
  justify-content: flex-end;

  padding: 0 1.45mm 0 0.8mm;
  border-left: 0.28mm solid var(--cd-document-border);

  font-size: 4.20mm;
  white-space: nowrap;
}

.cd-so .vat-label {
  padding-right: 12mm;
}

.cd-so .vat-rate {
  position: absolute;
  right: 1.7mm;
  top: 50%;
  transform: translateY(-50%);
  font-size: 3.52mm;
  white-space: nowrap;
}

.cd-so .grand-total-row {
  min-height: 8.90mm;
  border-top: 0.28mm solid var(--cd-document-border);
}

.cd-so .grand-total-row .total-label .label-th,
.cd-so .grand-total-row .total-value {
  font-weight: 700;
}

.cd-so .grand-total-row .total-value {
  font-size: 4.52mm;
}

/* =========================================================
   PRINT SAFETY
   ========================================================= */

.cd-so .document-info,
.cd-so .order-main,
.cd-so .items-table,
.cd-so .summary-section,
.cd-so .signature-section {
  page-break-inside: avoid;
}
